@Test
public void testCreate() throws Exception {
    int node1PortNumber = _portHelper.getNextAvailable();
    String helperAddress = "localhost:" + node1PortNumber;
    String groupName = "group";
    String nodeName = "node1";
    Map<String, Object> node1Attributes = _helper.createNodeAttributes(nodeName, groupName, helperAddress, helperAddress, nodeName, node1PortNumber);
    BDBHAVirtualHostNodeImpl node1 = (BDBHAVirtualHostNodeImpl) _helper.createHaVHN(node1Attributes);
    final String address = node1.getAddress();
    final String createTime = node1.getCreatedTime().toInstant().toString();
    final String updateTime = node1.getLastUpdatedTime().toInstant().toString();
    _helper.assertNodeRole(node1, NodeRole.MASTER);
    // stop node to avoid running into race when role change is reported after we performed the check
    node1.stop();
    assertEquals("Unexpected VHN log subject", "[grp(/group)/vhn(/node1)] ", node1.getVirtualHostNodeLogSubject().getLogString());
    assertEquals("Unexpected group log subject", "[grp(/group)] ", node1.getGroupLogSubject().getLogString());
    String attributes = String.format("{address=%s,context={je.rep.insufficientReplicasTimeout=2 s, je.rep.replicaAckTimeout=2 s},createdTime=%s,groupName=%s,helperAddress=%s,id=%s,lastUpdatedTime=%s,name=%s,permittedNodes=[%s],storePath=%s,type=%s,virtualHostInitialConfiguration={\n  \"type\" : \"BDB_HA\"\n}}", address, createTime, groupName, helperAddress, node1.getId(), updateTime, nodeName, address, node1.getStorePath(), node1.getType());
    String expectedMessage = HighAvailabilityMessages.CREATE(nodeName, String.valueOf(Outcome.SUCCESS), attributes).toString();
    verify(_eventLogger).message(argThat(new LogSubjectMatcher(node1.getVirtualHostNodeLogSubject())), argThat(new LogMessageMatcher(expectedMessage, HighAvailabilityMessages.CREATE_LOG_HIERARCHY)));
    expectedMessage = HighAvailabilityMessages.ROLE_CHANGED(node1.getName(), node1.getAddress(), NodeRole.WAITING.name(), NodeRole.MASTER.name()).toString();
    verify(_eventLogger).message(argThat(new LogSubjectMatcher(node1.getGroupLogSubject())), argThat(new LogMessageMatcher(expectedMessage, HighAvailabilityMessages.ROLE_CHANGED_LOG_HIERARCHY)));
}

