public void testStopVirtualHost_ClosesConnections() {
    String virtualHostName = getTestName();
    QueueManagingVirtualHost<?> virtualHost = createVirtualHost(virtualHostName);
    assertEquals("Unexpected state", State.ACTIVE, virtualHost.getState());
    assertEquals("Unexpected number of connections before connection registered", (long) 0, virtualHost.getConnectionCount());
    AMQPConnection modelConnection = getMockConnection();
    virtualHost.registerConnection(modelConnection);
    assertEquals("Unexpected number of connections after connection registered", (long) 1, virtualHost.getConnectionCount());
    ((AbstractConfiguredObject<?>) virtualHost).stop();
    assertEquals("Unexpected state", State.STOPPED, virtualHost.getState());
    assertEquals("Unexpected number of connections after virtualhost stopped", (long) 0, virtualHost.getConnectionCount());
    verify(modelConnection).closeAsync();
}

