@Test
public void testStateChanges() {
    QueueConsumer consumer = newConsumer();
    StateChangeListener<MessageInstance, EntryState> stateChangeListener = mock(StateChangeListener.class);
    _queueEntry.addStateChangeListener(stateChangeListener);
    _queueEntry.acquire(consumer);
    verify(stateChangeListener).stateChanged(eq(_queueEntry), eq(MessageInstance.AVAILABLE_STATE), isA(UnstealableConsumerAcquiredState.class));
    _queueEntry.makeAcquisitionStealable();
    verify(stateChangeListener).stateChanged(eq(_queueEntry), isA(UnstealableConsumerAcquiredState.class), isA(StealableConsumerAcquiredState.class));
    _queueEntry.removeAcquisitionFromConsumer(consumer);
    verify(stateChangeListener).stateChanged(eq(_queueEntry), isA(StealableConsumerAcquiredState.class), eq(NON_CONSUMER_ACQUIRED_STATE));
}

